import{_ as a,o as d,c as r,ak as i}from"./chunks/framework.CYL5YPWS.js";const w=JSON.parse('{"title":"Rewarded ads","description":"","frontmatter":{},"headers":[],"relativePath":"grindr-api/commerce/rewarded-ads.md","filePath":"generated/grindr-api/commerce/rewarded-ads.md"}'),t={name:"grindr-api/commerce/rewarded-ads.md"};function o(s,e,n,l,c,h){return d(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="rewarded-ads" tabindex="-1">Rewarded ads <a class="header-anchor" href="#rewarded-ads" aria-label="Permalink to “Rewarded ads”">​</a></h1><h2 id="report-rewarded-ad-consumption" tabindex="-1">Report rewarded ad consumption <a class="header-anchor" href="#report-rewarded-ad-consumption" aria-label="Permalink to “Report rewarded ad consumption”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Reports status of a rewarded ad watch. Send <code>STARTED</code> when the ad begins and <code>COMPLETED</code> when it finishes. A <code>COMPLETED</code> report grants the reward identified by <code>type</code> (e.g. <code>READ_RECEIPTS</code>).</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PUT /v1/rewarded-ads/consumption</span></span></code></pre></div><p>Body:</p><ul><li><code>source</code> — string, Ad mediation network that served the ad, e.g. <code>APPLOVIN</code>.</li><li><code>status</code> — <a href="/grindr-api/commerce/rewarded-ads#rewarded-ad-consumption-status">Rewarded Ad Consumption Status</a>, Lifecycle status being reported.</li><li><code>type</code> — <a href="/grindr-api/commerce/rewarded-ads#rewarded-ad-type">Rewarded Ad Type</a>, Reward being consumed.</li><li><code>adId</code> — string, Identifier of the ad instance, as reported by the ad SDK.</li></ul><h2 id="restrict-a-rewarded-ad-reward" tabindex="-1">Restrict a rewarded ad reward <a class="header-anchor" href="#restrict-a-rewarded-ad-reward" aria-label="Permalink to “Restrict a rewarded ad reward”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Updates the restriction for the given rewarded ad reward <code>type</code>, sent by the client when a reward should no longer be offered.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PUT /v1/rewarded-ads/rewards/restriction</span></span></code></pre></div><p>Body:</p><ul><li><code>type</code> — <a href="/grindr-api/commerce/rewarded-ads#rewarded-ad-type">Rewarded Ad Type</a>, Reward to restrict.</li></ul><h2 id="list-rewarded-ad-rewards" tabindex="-1">List rewarded ad rewards <a class="header-anchor" href="#list-rewarded-ad-rewards" aria-label="Permalink to “List rewarded ad rewards”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Returns the rewarded ad rewards available to the current user and their state. Watching an ad for an <code>ELIGIBLE</code> reward temporarily unlocks the corresponding feature (for example <code>READ_RECEIPTS</code>).</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v1/rewarded-ads/rewards</span></span></code></pre></div><p>Response:</p><ul><li><code>rewards</code> — array of <a href="/grindr-api/commerce/rewarded-ads#rewarded-ad-reward">Rewarded Ad Reward</a></li></ul><h2 id="rewarded-ad-type" tabindex="-1">Rewarded Ad Type <a class="header-anchor" href="#rewarded-ad-type" aria-label="Permalink to “Rewarded Ad Type”">​</a></h2><p>Feature that can be temporarily unlocked by watching a rewarded ad.</p><ul><li><code>LAST_VIEWED_ME_PROFILE</code> — Reveal the most recent profile that viewed you</li><li><code>ADS_FREE_SESSION</code> — Temporarily remove ads</li><li><code>READ_RECEIPTS</code> — Temporarily enable message read receipts</li><li><code>CASCADE_PROFILES_UNLOCK</code> — Unlock additional cascade (grid) profiles</li><li><code>TAPS_RECEIVED_UNLOCK</code> — Reveal taps you have received</li></ul><h2 id="rewarded-ad-reward-status" tabindex="-1">Rewarded Ad Reward Status <a class="header-anchor" href="#rewarded-ad-reward-status" aria-label="Permalink to “Rewarded Ad Reward Status”">​</a></h2><p>Current state of a rewarded ad reward for the requesting user.</p><ul><li><code>ELIGIBLE</code> — The user may watch an ad to activate this reward</li><li><code>ACTIVE</code> — The reward is currently unlocked; see <code>remainingTime</code></li><li><code>EXHAUSTED</code> — The reward has been used and is not currently available</li></ul><h2 id="rewarded-ad-interval" tabindex="-1">Rewarded Ad Interval <a class="header-anchor" href="#rewarded-ad-interval" aria-label="Permalink to “Rewarded Ad Interval”">​</a></h2><p>Unit of time that <code>duration</code> is measured in.</p><ul><li><code>&quot;DAYS&quot;</code></li><li><code>&quot;HOURS&quot;</code></li><li><code>&quot;MINUTES&quot;</code></li></ul><h2 id="rewarded-ad-consumption-status" tabindex="-1">Rewarded Ad Consumption Status <a class="header-anchor" href="#rewarded-ad-consumption-status" aria-label="Permalink to “Rewarded Ad Consumption Status”">​</a></h2><p>Lifecycle status reported while consuming a rewarded ad.</p><ul><li><code>STARTED</code> — The ad began playing</li><li><code>COMPLETED</code> — The ad finished and the reward should be granted</li></ul><h2 id="rewarded-ad-reward" tabindex="-1">Rewarded Ad Reward <a class="header-anchor" href="#rewarded-ad-reward" aria-label="Permalink to “Rewarded Ad Reward”">​</a></h2><p>State of a single rewarded ad reward. All fields are nullable.</p><ul><li><code>type</code> — <a href="/grindr-api/commerce/rewarded-ads#rewarded-ad-type">Rewarded Ad Type</a>, Feature this reward unlocks., optional</li><li><code>status</code> — <a href="/grindr-api/commerce/rewarded-ads#rewarded-ad-reward-status">Rewarded Ad Reward Status</a>, Current state of the reward., optional</li><li><code>duration</code> — long integer, Length of the unlock window, measured in <code>interval</code> units (e.g. <code>1</code> with interval <code>HOURS</code>)., optional</li><li><code>interval</code> — <a href="/grindr-api/commerce/rewarded-ads#rewarded-ad-interval">Rewarded Ad Interval</a>, Unit for <code>duration</code>., optional</li><li><code>remainingTime</code> — long integer, Time remaining before an <code>ACTIVE</code> reward expires. <code>null</code> unless the reward is active., optional</li><li><code>countdownTime</code> — long integer, Time remaining before an <code>EXHAUSTED</code> reward becomes <code>ELIGIBLE</code> again. <code>null</code> unless applicable., optional</li></ul>',34)])])}const u=a(t,[["render",o]]);export{w as __pageData,u as default};
